const crypto = require('crypto');

// Verify HMAC-SHA256 signature from Sahaj API
const signatureHeader = $input.item.headers['x-sahaj-signature'] || '';
const secret = $env.N8N_WEBHOOK_SECRET || 'sahaj-default-secret';
const bodyStr = JSON.stringify($input.item.body);
const expectedSig = 'sha256=' + crypto.createHmac('sha256', secret).update(bodyStr).digest('hex');

const isValid = signatureHeader === expectedSig || process.env.NODE_ENV !== 'production';

return [{
  json: {
    ...$input.item.body,
    signatureValid: isValid,
    deliveryId: $input.item.headers['x-sahaj-delivery'] || 'direct',
    receivedAt: new Date().toISOString()
  }
}];

const doc = $input.item.json;
const docLabel = doc.docType === 'income_proof' ? 'Income Proof (Salary Slip)' : (doc.docType === 'admission_letter' ? 'College Admission Letter' : 'Identity Document');

const msg = `Namaste! Sahaj Update: Your ${docLabel} has been verified successfully. Your loan application is now ready for comparison. Open your journey: https://sahaj.paytm.com/journey/${doc.journeyId}`;

return [{
  json: {
    journeyId: doc.journeyId,
    userId: doc.userId,
    channel: 'whatsapp',
    recipient: doc.userPhoneMasked || 'XXXXXX9876',
    message: msg,
    status: 'sent',
    timestamp: new Date().toISOString()
  }
}];

const doc = $input.item.json;
const msg = `Sahaj Notice: Your uploaded document requires human review. Our verification officer will review it shortly. Reference: ${doc.docId}`;

return [{
  json: {
    journeyId: doc.journeyId,
    userId: doc.userId,
    channel: 'sms',
    recipient: doc.userPhoneMasked || 'XXXXXX9876',
    message: msg,
    status: 'queued_review',
    timestamp: new Date().toISOString()
  }
}];
